import{_ as r,l,o as e,c as s,v as i,p as n,x as t,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"正胶与负胶","description":"","frontmatter":{"title":"正胶与负胶","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/positive-vs-negative.md","filePath":"litho/positive-vs-negative.md","lastUpdated":1789023840000}'),E={name:"litho/positive-vs-negative.md"};function c(m,a,A,_,B,D){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="正胶与负胶" tabindex="-1">正胶与负胶 <a class="header-anchor" href="#正胶与负胶" aria-label="Permalink to &quot;正胶与负胶&quot;">​</a></h1><div class="epigraph"><p>曝光区溶掉还是留下，是记录介质的极性：同一张空中像，正胶与负胶切出互补的浮雕，掩模明暗场要跟着换。</p><footer>—— 据 Reiser 对光刻胶极性的表述，以及 Mack 对正负胶与明暗场的产线讨论整理</footer></div><p><a href="/litho/focus-drilling">上一课</a>把成像与分辨率这门课收到走焦积分。扫描机写下的是剂量；缺口是记录介质如何把剂量切成浮雕——先钉极性，再谈具体化学。本课引入正胶与负胶。DNQ–酚醛从<a href="/litho/dnq-novolac">下一课</a>写起，不要在这里提前做 i 线配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>走焦与剂量环解决的是能量如何落到晶圆上。胶要回答：哪些区域在显影后留下。正胶（positive tone）：曝光区极性变了或抑制剂被破坏，碱性显影液溶掉曝光区，留下未曝光浮雕。负胶（negative tone）：曝光区交联或网络致密，显影液溶掉未曝光区，留下曝光浮雕。同一空中像，两种极性给出互补图形。</p><p>缺口不是再讲一次狭缝积分，而是：层要的是「孔」还是「岛」，决定胶的极性与掩模是明场还是暗场。把所有层默认成正胶，会在孔层、切层上走冤枉路；把极性写成「先进等于负胶」，又会忽略 DUV 逻辑后段长期以正胶为主的事实。</p><h3 id="极性不是先进指标" tabindex="-1">极性不是先进指标 <a class="header-anchor" href="#极性不是先进指标" aria-label="Permalink to &quot;极性不是先进指标&quot;">​</a></h3><p>Reiser 把抗蚀剂科学写成感光聚合物的反应与溶解；正负是溶解行为相对曝光的符号，不是节点世代。Mack 强调还要配掩模色调：暗场掩模配正胶打孔，明场配正胶打岛，负胶则对调。色调选错，MEEF 与缺陷偏好一起换边。</p><p><span class="marginnote">「正性显影 / 负性显影」（PTD / NTD）说的是显影液相对有机溶剂的另一套色调，不要与本课的正胶/负胶分子机制混名。本课只钉曝光区溶还是留。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选极性先问图形：要留下的是暗区还是亮区，缺陷是桥连更贵还是断线更贵，以及蚀刻要的是胶当掩模挡住哪里。正胶生态（显影、去胶、检测）在 KrF/ArF 上最熟；负胶在交联机械强度、某些孔与切层的亮区留下上有结构优势。EUV 金属氧化物胶多数走负胶工作点，那是后课化学，本课只承认极性可以跟化学家族绑定。</p><p>掩模：正胶 + 暗场 ≈ 曝光开口处开孔；正胶 + 明场 ≈ 曝光大面积、留下岛。负胶把这套对偶反过来。计算光刻的阈值模型要声明极性：同一张 \\(I(x)\\)，切「高于阈值溶掉」还是「高于阈值留下」，边的移动方向相反。</p><h3 id="后课默认" tabindex="-1">后课默认 <a class="header-anchor" href="#后课默认" aria-label="Permalink to &quot;后课默认&quot;">​</a></h3><p>说到 DUV 逻辑后段，默认正性 CAR，除非该层显式声明负胶或 NTD。说到「互补图形」，先问是换胶极性还是换掩模色调，两者可以互相替代一部分，但不能互相替代缺陷与侧壁的化学。</p>',14)),(e(),n(d,null,{default:t(()=>[h(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%89%82%E9%87%8F%22%5D%20--%3E%20POS%5B%22%E6%AD%A3%E8%83%B6%3A%20%E6%9B%9D%E5%85%89%E5%8C%BA%E6%BA%B6%E8%A7%A3%22%5D%0A%20%20I%20--%3E%20NEG%5B%22%E8%B4%9F%E8%83%B6%3A%20%E6%9B%9D%E5%85%89%E5%8C%BA%E7%95%99%E4%B8%8B%22%5D%0A%20%20POS%20--%3E%20BF%5B%22%E9%85%8D%E6%9A%97%E5%9C%BA%20%2F%20%E6%98%8E%E5%9C%BA%22%5D%0A%20%20NEG%20--%3E%20BF%0A%20%20BF%20--%3E%20REL%5B%22%E6%B5%AE%E9%9B%95%22%5D%0A%20%20REL%20--%3E%20DNQ%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20DNQ%20%E5%8C%96%E5%AD%A6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正胶的典型路径是抑制剂破坏（DNQ）或保护基脱落（后课 CAR）：溶解速率随曝光上升。负胶的典型路径是交联：分子量上升，溶解速率随曝光下降。阈值附近，正胶的边在「刚好溶得动」的等剂量线上，负胶的边在「刚好交联住」的等剂量线上。光学 ILS 相同，边的噪声对剂量的符号相反：过曝让正胶孔变大、负胶孔变小（在孔层的常见配置下），这是后课曝光宽容度必须声明极性的原因。</p><p>侧壁与倒塌：负胶交联膜往往更硬，高深宽比有时更抗塌；正胶脱保护膜在显影液里更像溶蚀。这是后课图形倒塌的化学前置，本课只记下极性会改机械与表面能，不写毛细公式。</p><p><span class="marginnote">明暗场还改掩模缺陷偏好：暗场上的针孔变成晶圆上的多余曝光。极性选定之后，掩模检验规格要跟着色调走，不能沿用上一层的版。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 PAG 分子、不写锡氧笼、不把某代接触孔「改用负胶」的新闻当普遍法则。也不讨论图像反转工艺（image reversal）的完整流程——那是正胶化学上再烘再曝光得到负像，属于特例，后课需要时再点名。</p><p>Focus drilling 摊开的是焦轴上的剂量叠加，极性仍然在显影这一步才出现；走焦不会把正胶变成负胶。产能会计里的剂量，对两种极性都是 \\(\\mathrm{mJ/cm^2}\\)，灵敏度曲线形状不同，wph 账按该层 \\(E_0\\) 走。成像课到此把「能量写下」交出来；化学课从极性开始，后课才进入 DNQ 与 CAR 的分子通道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正胶溶曝光区，负胶留曝光区；同一空中像切出互补浮雕。</li><li>极性要与掩模明暗场一起选，并声明给阈值模型。</li><li>正负不是先进指标；DUV 后段默认正胶，孔/切层可以另选。</li><li>PTD/NTD 是显影色调，不要与正/负胶混名。</li><li>下一课从 DNQ–Novolac 进入具体正胶化学。</li><li>走焦不改极性；wph 按该层 \\(E_0\\) 走，不按正负胶口号走。</li><li>出处：Reiser, <em>Photoreactive Polymers</em>；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',9))])}const v=r(E,[["render",c]]);export{f as __pageData,v as default};
